/**
 * @name Untrusted URL redirection in httpx client
 * @description Detects flows from remote input into request URL parameters that might cause SSRF or open redirect when httpx is used as a proxy client.
 * @kind path-problem
 * @problem.severity error
 * @id py/httpx-untrusted-url
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HttpxUrlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module HttpxUrlFlow = TaintTracking::Global<HttpxUrlConfig>;
import HttpxUrlFlow::PathGraph

from HttpxUrlFlow::PathNode source, HttpxUrlFlow::PathNode sink
where HttpxUrlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data flows into httpx request URL, which may lead to SSRF or open redirect.", source.getNode(), "user input"
